import java.util.*;

class Bank {
    private final Map<Integer, Long> accounts = new HashMap<>();

    public Bank(long[] balance) {
        for (int i = 0; i < balance.length; i++) {
            accounts.put(i + 1, balance[i]);
        }
    }

    public boolean transfer(int account1, int account2, long money) {
        if (!accounts.containsKey(account1) || !accounts.containsKey(account2)) {
            return false;
        }
        long fromBalance = accounts.get(account1);
        if (fromBalance < money) {
            return false;
        }
        accounts.put(account1, fromBalance - money);
        accounts.put(account2, accounts.get(account2) + money);
        return true;
    }

    public boolean deposit(int account, long money) {
        if (!accounts.containsKey(account)) {
            return false;
        }
        accounts.put(account, accounts.get(account) + money);
        return true;
    }

    public boolean withdraw(int account, long money) {
        Long balance = accounts.get(account);
        if (balance == null || balance < money) {
            return false;
        }
        accounts.put(account, balance - money);
        return true;
    }
}

class Bank {
    private static class Account {
        long balance;

        Account(long balance) {
            this.balance = balance;
        }

        boolean canWithdraw(long money) {
            return balance >= money;
        }
    }

    private final Account[] accounts;

    public Bank(long[] balance) {
        accounts = new Account[balance.length + 1];
        for (int i = 0; i < balance.length; i++) {
            accounts[i + 1] = new Account(balance[i]);
        }
    }

    public boolean transfer(int account1, int account2, long money) {
        Account from = get(account1);
        Account to = get(account2);
        if (from == null || to == null || !from.canWithdraw(money)) {
            return false;
        }
        from.balance -= money;
        to.balance += money;
        return true;
    }

    public boolean deposit(int account, long money) {
        Account target = get(account);
        if (target == null) {
            return false;
        }
        target.balance += money;
        return true;
    }

    public boolean withdraw(int account, long money) {
        Account target = get(account);
        if (target == null || !target.canWithdraw(money)) {
            return false;
        }
        target.balance -= money;
        return true;
    }

    private Account get(int account) {
        if (account <= 0 || account >= accounts.length) {
            return null;
        }
        return accounts[account];
    }
}

import java.util.*;

class Bank {
    private final List<Long> balances = new ArrayList<>();

    public Bank(long[] balance) {
        balances.add(0L);
        for (long value : balance) {
            balances.add(value);
        }
    }

    public boolean transfer(int account1, int account2, long money) {
        if (!canWithdraw(account1, money) || !validAccount(account2)) {
            return false;
        }
        applyDelta(account1, -money);
        applyDelta(account2, money);
        return true;
    }

    public boolean deposit(int account, long money) {
        if (!validAccount(account)) {
            return false;
        }
        applyDelta(account, money);
        return true;
    }

    public boolean withdraw(int account, long money) {
        if (!canWithdraw(account, money)) {
            return false;
        }
        applyDelta(account, -money);
        return true;
    }

    private boolean validAccount(int account) {
        return account > 0 && account < balances.size();
    }

    private boolean canWithdraw(int account, long money) {
        return validAccount(account) && balances.get(account) >= money;
    }

    private void applyDelta(int account, long delta) {
        balances.set(account, balances.get(account) + delta);
    }
}
